class HelperMethod {

    static Double getSanitizeDouble(String value) {
        if (value == null)
            return 0d
        String sanitized = value.replaceAll("[^0-9.\\-]", "")
        if (!sanitized || sanitized == "-" || sanitized == ".")
            return 0d
        try {
            return Double.parseDouble(sanitized)
        } catch (Exception e) {
            return 0d
        }
    }

    static Boolean isPatternMatchWithString(String pattern, String value) {
        value != null && pattern != null && value.find(pattern)
    }

    static String getSanitizedString(String value) {
        value?.trim()
    }

    static String dateToString(Date date, String format = "dd/MM/yyyy") {
        date ? date.format(format) : ""
    }

