    static void extractBasicInformationFromDownloadedCurrentAccount(ProcessedBankStatementVO processedBankStatementVO) {
        SimpleDateFormat format = new SimpleDateFormat("dd-MMM-yyyy")
        if (!AppUtil.isValidStatementFile(processedBankStatementVO.processBankStatementCO.textFile, ["Account\\s*No", "Statement\\s*Dt"])) {
            return
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(processedBankStatementVO.processBankStatementCO.textFile), "UTF-8"))
        BasicDetailsResponse basicDetailsResponse = processedBankStatementVO.basicDetails
        String line = ""
        while (line != null) {
            line = reader.readLine()
            if (StringUtils.isBlank(line)) {
                continue
            } else if (line.find("Account\\s*No")) {
                basicDetailsResponse.accountNumber = line.find("[0-9]{15}")?.trim()
                Pattern datePattern = Pattern.compile("(([0-9])|([0-2][0-9])|([3][0-1]))-(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)-....")
                Matcher dateMatcher = datePattern.matcher(line)
                List<String> dateList = []
                while (dateMatcher.find()) {
                    dateList << dateMatcher.group()
                }
                if (dateList.size() == 2) {
                    String fromDate = dateList.get(0)
                    String toDate = dateList.get(1)
                    basicDetailsResponse.fromDate = format.parse(fromDate).toCalendar()
                    basicDetailsResponse.toDate = format.parse(toDate).toCalendar()
                }
            } else if (line.find("Mode\\s*Of\\s*Operation")) {
                line = reader.readLine()
                basicDetailsResponse.accountHolderName = line?.trim()
                break
            }
        }
        processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.PARTIALLY_PARSED
        processedBankStatementVO.statementStatus.message = "Basic details extracted Successfully"
        reader.close()
    }

