            String html = tables.get(0).toHtml()
            Integer lastPageSize = 0
            org.jsoup.nodes.Document jsoupDocument = Jsoup.parse(html)
            if (!jsoupDocument.select("table").empty) {
                jsoupDocument.select("tr").eachWithIndex { tr, index ->
                    String trText = tr.text()
                    if (trText.find("Statement[\\s]*Period"))
                        firstTableIndex = index + 2
                    else if (trText.find("Account[\\s]*Statement[\\s]*for") && firstTableIndex <= 1) {
                        firstTableIndex = index + 1
                    }
                    if (trText.find("Page") && lastTableIndex < 1)
