/**
 * Whether the given value is a month name date which has to be normalised before it can be
 * parsed, ie. a date having spaces around its separators, a date whose month name got extracted
 * with the well known `JUY` error or a date printed without any separator.
 */
public static Boolean isMonthNameDateNeedingNormalisation(String value) {
    String trimmedValue = value?.trim()
    if (!trimmedValue || !trimmedValue.find(MONTH_NAME_DATE_REGEX)) {
        return Boolean.FALSE
    }
    Boolean hasJulyExtractionError = trimmedValue.find("(?i:JUY)") as Boolean
    Boolean hasSpacedSeparator = (trimmedValue.find("-") && trimmedValue.find("[\\s]")) as Boolean
    Boolean hasNoSeparator = !trimmedValue.find("[-\\s]")
    (hasJulyExtractionError || hasSpacedSeparator || hasNoSeparator) as Boolean
}

/**
 * Normalises a month name date to its compact form, ex : `03- JUY- 2017` ===>>> `03JUL2017`.
 */
public static String normaliseMonthNameDate(String value) {
    String normalisedValue = value.trim().replaceAll("[\\s]", "").replaceAll("-", "")
    normalisedValue.replaceAll("JUY", "JUL").replaceAll("Juy", "Jul").replaceAll("juy", "jul")
}

public static String processValue(String headerValue) {
    if (headerValue == null) {
        return headerValue
    }
    if (headerValue.length() == 1 && headerValue.find("-")) {
        headerValue = headerValue.replaceAll("-", "")
    } else if (headerValue.find("^[0-3][0-9]-[0-1][0-9]-[0-9]{4}[\\s]*(([0-1][0-9]:[0-6][0-9]:[0-6][0-9][\\s]*(AM|PM))|([0-1]?[0-9]:[0-6][0-9]))")) {
        headerValue = headerValue.find("[0-3][0-9]-[0-1][0-9]-[0-9]{4}")
    } else if (headerValue.find("^[0-1][0-9]-[0-3][0-9]-[0-9]{4}[\\s]*(([0-1][0-9]:[0-6][0-9]:[0-6][0-9][\\s]*(AM|PM))|([0-1]?[0-9]:[0-6][0-9]))")) {
        headerValue = headerValue.find("[0-1][0-9]-[0-3][0-9]-[0-9]{4}")
    } else if (headerValue.find("^[0-3][0-9]-[0-1][0-9]-[0-9]{4}[\\s]*-?[0-9]*[\\s]*(([0-1][0-9]:[0-6][0-9]:[0-6][0-9][\\s]*(AM|PM))|([0-1]?[0-9]:[0-6][0-9]))")) {
        headerValue = headerValue.find("[0-3][0-9]-[0-1][0-9]-[0-9]{4}")
    } else if (headerValue.find("^[0-3][0-9]/[0-1][0-9]/[0-9]{4}[\\s]*(([0-1][0-9]:[0-6][0-9]:[0-6][0-9][\\s]*(AM|PM))|(([0-1]?[0-9]|2[0-3]):[0-6][0-9]))")) {
        headerValue = headerValue.replaceAll("[\\s]*[0-1][0-9]:[0-6][0-9]:[0-6][0-9] (AM|PM)", "").replaceAll("[\\s]*([0-1]?[0-9]|2[0-3]):[0-6][0-9]", "")
    } else if (headerValue.find("^[0-3][0-9]/[0-1][0-9]/[\\s]*[0-9]{4}")) {
        headerValue = headerValue.replaceAll(" ", "")
    } else if (headerValue.find("^[0-3][0-9]-[A-Z][a-z]{2}-[0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2}")) {
        headerValue = headerValue.replaceAll("[0-9]{2}:[0-9]{2}:[0-9]{2}", "").trim()
    } else if (isMonthNameDateNeedingNormalisation(headerValue)) {
        headerValue = normaliseMonthNameDate(headerValue)
    } else if (headerValue.find("([0-3]?[0-9]-[\\s]*[A-z]{3,4}-[\\s]*[0-9]{2,4})")) {
        headerValue = headerValue.replaceAll(" ", "").trim()
    } else if (headerValue.find("^-\$")) {
        headerValue = headerValue.replaceAll("-", "").trim()
    }
    return headerValue
}

