     * instead of breaking the whole row.
     */
    public static String cellText(Elements rowElements, Integer columnIndex) {
        if (rowElements == null || columnIndex == null || columnIndex < 0) {
            return ""
        }
        (rowElements.eq(columnIndex).text() ?: "").trim()
    }

    public static String cellText(Element element, Integer columnIndex) {
        cellText(element?.select("td"), columnIndex)
    }

    /** Appends a multi line description part to the description collected so far. */
    public static String appendDescription(String description, String descriptionPart) {
        String part = descriptionPart?.trim()
        if (!part) {
            return description ?: ""
        }
        description?.trim() ? description.trim() + " " + part : part
    }

    /** Whether the row is a repeated transaction header row, a total row or any other junk row. */
    public static Boolean isJunkTransactionRow(String dateValue, String descriptionValue) {
        Map<String, String> headerMap = headerDictionary()
        ((dateValue && dateValue.trim().find(headerMap.junk_date)) ||
                (descriptionValue && descriptionValue.trim().find(headerMap.junk_date))) as Boolean
    }

    /** Whether the row holds the balance brought forward / opening balance of the statement. */
    public static Boolean isOpeningBalanceRow(String descriptionValue) {
        (descriptionValue && descriptionValue.trim().find(headerDictionary().balance_brought_forward)) as Boolean
    }

    /** Whether the very first row of the extracted table is the header row of the table. */
    public static Boolean isTransactionHeaderRow(Element element, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
        String dateValue = cellText(element, bankTransactionHeaderIndex.transactionDateIndex)
        String descriptionValue = cellText(element, bankTransactionHeaderIndex.descriptionIndex)
        (dateValue && (dateValue.find("[A-z]{4,}") || isJunkTransactionRow(dateValue, descriptionValue))) as Boolean
    }

    /** An amount column holding nothing, a dash or a zero has to be treated as an empty column. */
    public static Boolean isBlankAmountValue(String amountValue) {
        (!amountValue || amountValue.find("^[\\s]*(-[\\s]*)?\$") || amountValue.find("^[\\s]*[0]*[.]?[0]*[\\s]*\$")) as Boolean
    }

    /**
     * Assigns the amount along with its direction (debit or credit) to the transaction, no matter
     * whether the statement holds separate debit and credit columns or a single amount column with
     * a debit/credit indicator.
     */
    public static void assignAmountAndType(BankTransactionResponse bankTransactionResponse, Elements rowElements,
                                           BankTransactionHeaderIndex bankTransactionHeaderIndex) {
        String debit = cellText(rowElements, bankTransactionHeaderIndex.debitIndex)
        String credit = cellText(rowElements, bankTransactionHeaderIndex.creditIndex)
        String amount = cellText(rowElements, bankTransactionHeaderIndex.amountIndex)
        String amountType = cellText(rowElements, bankTransactionHeaderIndex.amountTypeIndex)
        if (!isBlankAmountValue(debit)) {
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(debit)
            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
        }
        if (!isBlankAmountValue(credit) && (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(credit)
            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
        }
        if (!isBlankAmountValue(amount) && (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
            if (amount.toLowerCase().find("cr")) {
                bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
            } else if (amount.toLowerCase().find("dr")) {
                bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
            }
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(amount.replaceAll("(?i:(cr|dr))", ""))
        }
        if (amountType) {
            bankTransactionResponse.type = amountType.toLowerCase().find("cr") ? Enums.BankTransactionType.CREDIT :
                    Enums.BankTransactionType.DEBIT
        }
    }

    /**
     * Creates the opening balance transaction out of the balance brought forward row of the
     * statement so that the opening balance printed on the statement is not lost.
     */
    public
    static BankTransactionResponse openingBalanceTransactionFromRow(Elements rowElements, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
        String balance = cellText(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex)
        BankTransactionResponse bankTransactionResponse = BankUtil.createOpeningBalanceTransaction(BankUtil.processBalanceAmount(balance))
        bankTransactionResponse.transactionDate = parseStatementDate(cellText(rowElements, bankTransactionHeaderIndex.transactionDateIndex))
        bankTransactionResponse.valueDate = parseStatementDate(cellText(rowElements, bankTransactionHeaderIndex.valueDateIndex)) ?:
                bankTransactionResponse.transactionDate
        bankTransactionResponse
    }

    public
    static void extractTransactionsFromHTMLHavingDescriptionAboveDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            if (!elements || elements.isEmpty()) {
                continue
            }
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (isTransactionHeaderRow(elements.first(), bankTransactionHeaderIndex)) {
                elements.remove(0)
            }
            Integer elementCount = elements.size()
            Integer lineCount = 0
            String description = ""
            String pendingDate = ""
            while (lineCount < elementCount) {
                try {
                    Elements rowElements = elements.get(lineCount).select("td")
                    String date = cellText(rowElements, bankTransactionHeaderIndex.transactionDateIndex)
                    String descriptionValue = cellText(rowElements, bankTransactionHeaderIndex.descriptionIndex)
                    String balance = cellText(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex)
                    if (isJunkTransactionRow(date, descriptionValue)) {
                        description = ""
                        pendingDate = ""
                    } else if (isOpeningBalanceRow(descriptionValue)) {
                        if (processedBankStatementVO.bankTransactionList.size() == 0 && balance) {
                            processedBankStatementVO.bankTransactionList << openingBalanceTransactionFromRow(rowElements, bankTransactionHeaderIndex)
                        }
                        description = ""
                        pendingDate = ""
                    } else if (balance) {
//                      A row holding a balance without holding a date of its own belongs to the date of the transaction above it.
                        Date transactionDate = parseStatementDate(date) ?: parseStatementDate(pendingDate) ?:
                                (processedBankStatementVO.bankTransactionList ? processedBankStatementVO.bankTransactionList.last().transactionDate : null)
                        if (transactionDate) {
                            BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                            bankTransactionResponse.transactionDate = transactionDate
                            bankTransactionResponse.valueDate = parseStatementDate(cellText(rowElements, bankTransactionHeaderIndex.valueDateIndex))
                            bankTransactionResponse.description = appendDescription(description, descriptionValue)
                            bankTransactionResponse.remark = cellText(rowElements, bankTransactionHeaderIndex.chequeNoIndex)
                            bankTransactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(balance)
                            assignAmountAndType(bankTransactionResponse, rowElements, bankTransactionHeaderIndex)
                            processedBankStatementVO.bankTransactionList << bankTransactionResponse
                        }
                        description = ""
                        pendingDate = ""
                    } else {
                        description = appendDescription(description, descriptionValue)
                        pendingDate = pendingDate ?: date
                    }
                } catch (Exception e) {
                    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                    processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                    processedBankStatementVO.statementStatus.message = "Exception occurred during parsing ${processedBankStatementVO.processBankStatementCO.bank} download statement 'HTMLHavingDescriptionAboveDate' ====>>>>>> ${e.message}"
                    log.error(processedBankStatementVO.statementStatus.message, e)
                }
                lineCount += 1
            }
        }
        if (processedBankStatementVO.bankTransactionList.size() != 0) {
            BankUtil.checkForOpeningBalanceTransaction(processedBankStatementVO.bankTransactionList,
                    processedBankStatementVO.basicDetails?.fromDate?.getTime())
            BankUtil.findFromAndToDate(processedBankStatementVO.bankTransactionList.first(),
                    processedBankStatementVO.bankTransactionList.last(), processedBankStatementVO.basicDetails)
            BankUtil.addCreditOrDebitAndBalanceForTransaction(processedBankStatementVO)
        }
    }

