public
static String extractAccountHolderName(List<String> header, ProcessedBankStatementVO processedBankStatementVO) {
    String accountHolder = ""
    for (int lineNumber = 0; (lineNumber < header.size() && !accountHolder); lineNumber++) {
        try {
            String line = header.get(lineNumber)
            if (StringUtils.isBlank(line)) {
                continue
            } else if (line.find("Acc[\\s]*name")) {
                accountHolder = line.find("(?<=name\\s).*(?=\\sAccount)") ?: line.split("Acc[\\s]*name")[1]?.replace(":", "")
            } else if (line.find("Statement[\\s]*Date")) {
