/** Whether the row is a repeated transaction header row, a total row or any other junk row. */
public static Boolean isJunkTransactionRow(String dateValue, String descriptionValue) {
    Map<String, String> headerMap = headerDictionary()
    ((dateValue && dateValue.trim().find(headerMap.junk_date)) ||
            (descriptionValue && descriptionValue.trim().find(headerMap.junk_date))) as Boolean
}

/**
 * A row which does not hold a date of its own inherits the date of the transaction above it,
 * hence the total / carried forward rows of the statement have to be recognised as junk rows
 * even when their label is not printed within the description column.
 */
public static Boolean isJunkRow(Element element) {
    String rowText = (element?.text() ?: "").trim()
    (rowText && rowText.find(headerDictionary().junk_row)) as Boolean
}

